CREATE POLICY "checkin_photos_read_own_or_personal" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'check-in-photos' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(), 'personal')));
CREATE POLICY "checkin_photos_insert_own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'check-in-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "checkin_photos_update_own" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'check-in-photos' AND (storage.foldername(name))[1] = auth.uid()::text) WITH CHECK (bucket_id = 'check-in-photos' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "checkin_photos_delete_own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'check-in-photos' AND (storage.foldername(name))[1] = auth.uid()::text);